import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  interpolateColors,
  delayRender,
  continueRender,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module level font loading for fallback/secondary high-end Sans-Serif font
const { fontFamily: interFamily } = loadInter();

// Custom Brand Font Loading from Malloy Guidelines
if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const format = "opentype"; // .otf format
    const font = new FontFace(family, `url('${url}') format('${format}')`);
    font.load()
      .then(() => {
        document.fonts.add(font);
        continueRender(handle);
      })
      .catch((err) => {
        console.log(`Error loading ${family}`, err);
        continueRender(handle);
      });
  };
  loadCustomFont(
    "Believe-Font",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/6e3f2edcbb584480b2d9a1404eee140c.otf"
  );
}



export type DollarDeclineProps = Record<string, any>;

const DollarDecline: React.FC<DollarDeclineProps> = ({
  backgroundColor = "#060606",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#febf10",
  titlePart1 = "Purchasing Power of",
  titlePart2 = "One U.S. Dollar",
  declineLabel = "Decline",
  declinePercentage = "96%",
  lineThickness = 4,
  dotSize = 12,
  cardOpacity = 0.85,
  titlePart1FontFamily = "Believe-Font",
  titlePart2FontFamily = "Believe-Font",
  declineLabelFontFamily = "Believe-Font",
  declinePercentFontFamily = "Believe-Font",
  axisFontFamily = "Believe-Font",
  valuesFontFamily = "Believe-Font",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const durationInFrames = durationInSeconds * fps;

  // Resolve background color parser safety
  const resolvedBg = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Sizing definitions responsive to composition canvas
  const cardWidth = width * 0.74;
  const cardHeight = height * 0.7;
  const cardLeft = (width - cardWidth) / 2;
  const cardTop = (height - cardHeight) / 2;

  // Chart coordinate constraints inside the glass card
  const chartLeft = cardWidth * 0.08;
  const chartRight = cardWidth * 0.68;
  const chartTop = cardHeight * 0.32;
  const chartBottom = cardHeight * 0.82;

  // Map of 6 coordinate nodes based on actual storyboard data
  const rawPoints = [
    { year: "1930", value: 1.0 },
    { year: "1950", value: 0.83 },
    { year: "1970", value: 0.61 },
    { year: "1990", value: 0.38 },
    { year: "2010", value: 0.2 },
    { year: "2026", value: 0.06 },
  ];

  const points = rawPoints.map((p, i) => {
    const x = chartLeft + (i / 5) * (chartRight - chartLeft);
    const y =
      chartBottom -
      ((p.value - 0.06) / (1.0 - 0.06)) * (chartBottom - chartTop);
    return { ...p, x, y };
  });

  // Timings: Path sweep draws from 8% to 72% of total video duration
  const startFrame = Math.round(durationInFrames * 0.08);
  const endFrame = Math.round(durationInFrames * 0.72);
  const revealDuration = Math.round(durationInFrames * 0.15);

  const drawProgress = interpolate(frame, [startFrame, endFrame], [0, 1], {
    easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate coordinates of the moving glowing dot using cubic Bezier interpolation
  const getBezierPoint = (t: number, pts: typeof points) => {
    if (t <= 0) return pts[0];
    if (t >= 1) return pts[pts.length - 1];

    const numSegments = pts.length - 1;
    const rawSeg = t * numSegments;
    const segIndex = Math.min(numSegments - 1, Math.floor(rawSeg));
    const localT = rawSeg - segIndex;

    const p0 = pts[segIndex];
    const p1 = pts[segIndex + 1];

    const cp1 = { x: p0.x + (p1.x - p0.x) * 0.4, y: p0.y };
    const cp2 = { x: p1.x - (p1.x - p0.x) * 0.4, y: p1.y };

    const mt = 1 - localT;
    const x =
      mt * mt * mt * p0.x +
      3 * mt * mt * localT * cp1.x +
      3 * mt * localT * localT * cp2.x +
      localT * localT * localT * p1.x;
    const y =
      mt * mt * mt * p0.y +
      3 * mt * mt * localT * cp1.y +
      3 * mt * localT * localT * cp2.y +
      localT * localT * localT * p1.y;

    return { x, y };
  };

  const dotPos = getBezierPoint(drawProgress, points);

  // Partial SVG Path generation using de Casteljau's algorithm
  const getPartialPath = (t: number, pts: typeof points) => {
    if (t <= 0) return "";
    const numSegments = pts.length - 1;
    const currentProgress = t * numSegments;

    let d = `M ${pts[0].x} ${pts[0].y}`;

    for (let i = 0; i < numSegments; i++) {
      const p0 = pts[i];
      const p1 = pts[i + 1];

      const cp1 = { x: p0.x + (p1.x - p0.x) * 0.4, y: p0.y };
      const cp2 = { x: p1.x - (p1.x - p0.x) * 0.4, y: p1.y };

      if (currentProgress >= i + 1) {
        d += ` C ${cp1.x} ${cp1.y}, ${cp2.x} ${cp2.y}, ${p1.x} ${p1.y}`;
      } else if (currentProgress > i) {
        const localT = currentProgress - i;

        const l1 = {
          x: p0.x + (cp1.x - p0.x) * localT,
          y: p0.y + (cp1.y - p0.y) * localT,
        };
        const l2 = {
          x: cp1.x + (cp2.x - cp1.x) * localT,
          y: cp1.y + (cp2.y - cp1.y) * localT,
        };
        const l3 = {
          x: cp2.x + (p1.x - cp2.x) * localT,
          y: cp2.y + (p1.y - cp2.y) * localT,
        };

        const h1 = {
          x: l1.x + (l2.x - l1.x) * localT,
          y: l1.y + (l2.y - l1.y) * localT,
        };
        const h2 = {
          x: l2.x + (l3.x - l2.x) * localT,
          y: l2.y + (l3.y - l2.y) * localT,
        };

        const b = {
          x: h1.x + (h2.x - h1.x) * localT,
          y: h1.y + (h2.y - h1.y) * localT,
        };

        d += ` C ${l1.x} ${l1.y}, ${h1.x} ${h1.y}, ${b.x} ${b.y}`;
        break;
      }
    }
    return d;
  };

  const activePathString = getPartialPath(drawProgress, points);

  // Base faint background curve
  let baseCurveString = `M ${points[0].x} ${points[0].y}`;
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i];
    const p1 = points[i + 1];
    const cp1x = p0.x + (p1.x - p0.x) * 0.4;
    const cp1y = p0.y;
    const cp2x = p1.x - (p1.x - p0.x) * 0.4;
    const cp2y = p1.y;
    baseCurveString += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p1.x} ${p1.y}`;
  }

  // Camera push-in scale factor
  const cameraScale = interpolate(frame, [0, durationInFrames], [0.97, 1.025], {
    easing: Easing.out(Easing.quad),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Diagonal reflection stripe sweep
  const sweepX = interpolate(
    frame,
    [Math.round(durationInFrames * 0.1), Math.round(durationInFrames * 0.52)],
    [-cardWidth * 0.6, cardWidth * 1.5],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Title fade in
  const titleOpacity = interpolate(frame, [0, Math.round(durationInFrames * 0.12)], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, Math.round(durationInFrames * 0.12)], [15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Reveal factor helper for coordinates & text as the sweep passes them
  const getPointReveal = (index: number) => {
    const threshold = index / 5;
    if (drawProgress < threshold) return 0;
    return interpolate(drawProgress, [threshold, threshold + 0.05], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  };

  // Pulse effect for the end-point once completed
  const endDotPulse =
    drawProgress === 1.0 ? Math.sin(frame * 0.18) * 0.12 + 1.0 : 1.0;

  // "96% Decline" label timing after sweeping completes
  const declineProgress = interpolate(
    frame,
    [endFrame, endFrame + revealDuration],
    [0, 1],
    {
      easing: Easing.bezier(0.16, 1, 0.3, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Dynamic Font Families assignment
  const fontMap = (enumName: string) => {
    if (enumName === "Believe-Font") return "Believe-Font";
    if (enumName === "Inter") return interFamily;
    return "sans-serif";
  };

  const titlePart1Fam = fontMap(titlePart1FontFamily);
  const titlePart2Fam = fontMap(titlePart2FontFamily);
  const declineLabelFam = fontMap(declineLabelFontFamily);
  const declinePercentFam = fontMap(declinePercentFontFamily);
  const axisFam = fontMap(axisFontFamily);
  const valuesFam = fontMap(valuesFontFamily);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: resolvedBg,
        backgroundImage: `
          radial-gradient(circle at 50% 50%, rgba(254, 191, 16, 0.055) 0%, rgba(0, 0, 0, 0) 80%),
          radial-gradient(rgba(255, 255, 255, 0.02) 1.5px, transparent 1.5px)
        `,
        backgroundSize: "100% 100%, 36px 36px",
        overflow: "hidden",
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      {/* Outer Card Glow backdrop layer */}
      <div
        style={{
          position: "absolute",
          left: cardLeft,
          top: cardTop,
          width: cardWidth,
          height: cardHeight,
          borderRadius: 32,
          backgroundColor: `${primaryColor}06`,
          filter: "blur(60px)",
          transform: `scale(${cameraScale})`,
          pointerEvents: "none",
          zIndex: 0,
          transition: "none",
        }}
      />

      {/* Main Glassmorphic Card Container */}
      <div
        style={{
          position: "absolute",
          left: cardLeft,
          top: cardTop,
          width: cardWidth,
          height: cardHeight,
          borderRadius: 32,
          backgroundColor: `rgba(10, 10, 10, ${cardOpacity})`,
          backdropFilter: "blur(40px)",
          WebkitBackdropFilter: "blur(40px)",
          border: "1px solid rgba(255, 255, 255, 0.08)",
          boxShadow: `
            0 30px 80px rgba(0, 0, 0, 0.8),
            inset 0 1px 0 rgba(255, 255, 255, 0.12),
            inset 0 -1px 0 rgba(254, 191, 16, 0.15)
          `,
          transform: `scale(${cameraScale})`,
          overflow: "hidden",
          zIndex: 1,
          transition: "none",
        }}
      >
        {/* Dynamic Sweeping Glass Glow Reflection */}
        <div
          style={{
            position: "absolute",
            top: 0,
            bottom: 0,
            width: cardWidth * 0.25,
            background:
              "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.06) 50%, rgba(255,255,255,0) 100%)",
            transform: `translateX(${sweepX}px) skewX(-28deg)`,
            pointerEvents: "none",
            zIndex: 1,
            transition: "none",
          }}
        />

        {/* Info Header in the upper right quadrant */}
        <div
          style={{
            position: "absolute",
            right: cardWidth * 0.08,
            top: cardHeight * 0.08,
            textAlign: "right",
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            zIndex: 2,
            transition: "none",
          }}
        >
          <div
            style={{
              fontFamily: titlePart1Fam,
              fontSize: "1.4vw",
              color: "rgba(255, 255, 255, 0.55)",
              fontWeight: 400,
              letterSpacing: "1px",
              marginBottom: 4,
              transition: "none",
            }}
          >
            {titlePart1}
          </div>
          <div
            style={{
              fontFamily: titlePart2Fam,
              fontSize: "3vw",
              color: primaryColor,
              fontWeight: "bold",
              textShadow: `0 0 25px ${primaryColor}20`,
              transition: "none",
            }}
          >
            {titlePart2}
          </div>
        </div>

        {/* SVG Canvas for Graph lines & alignments */}
        <svg
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: cardWidth,
            height: cardHeight,
            overflow: "visible",
            zIndex: 2,
            transition: "none",
          }}
        >
          {/* Main X-Axis horizontal line */}
          <line
            x1={chartLeft}
            y1={chartBottom + 10}
            x2={chartRight}
            y2={chartBottom + 10}
            stroke="rgba(255, 255, 255, 0.15)"
            strokeWidth={1.5}
            style={{ transition: "none" }}
          />

          {/* Dotted axis lines and node alignment rules */}
          {points.map((p, i) => {
            const revealVal = getPointReveal(i);
            const currentY = p.y + (chartBottom + 10 - p.y) * revealVal;

            return (
              <React.Fragment key={`lines-${p.year}`}>
                {/* Vertical dash alignment marker */}
                {revealVal > 0 && (
                  <line
                    x1={p.x}
                    y1={p.y}
                    x2={p.x}
                    y2={currentY}
                    stroke="rgba(255, 255, 255, 0.12)"
                    strokeWidth={1.2}
                    strokeDasharray="4 4"
                    style={{ transition: "none" }}
                  />
                )}
                {/* Axis Intersection Marker */}
                <circle
                  cx={p.x}
                  cy={chartBottom + 10}
                  r={3}
                  fill={revealVal > 0.1 ? primaryColor : "rgba(255, 255, 255, 0.2)"}
                  style={{ transition: "none" }}
                />
              </React.Fragment>
            );
          })}

          {/* Faint static trajectory path */}
          <path
            d={baseCurveString}
            fill="none"
            stroke="rgba(255, 255, 255, 0.04)"
            strokeWidth={lineThickness}
            style={{ transition: "none" }}
          />

          {/* Active Glowing Progress Path Layer 1 (Glowing Bloom shadow) */}
          {activePathString && (
            <path
              d={activePathString}
              fill="none"
              stroke={primaryColor}
              strokeWidth={lineThickness * 3.5}
              opacity={0.16}
              style={{
                filter: "blur(6px)",
                transition: "none",
              }}
            />
          )}

          {/* Active Glowing Progress Path Layer 2 (Solid core) */}
          {activePathString && (
            <path
              d={activePathString}
              fill="none"
              stroke={primaryColor}
              strokeWidth={lineThickness}
              opacity={1}
              style={{ transition: "none" }}
            />
          )}

          {/* Glowing travelling dot assembly */}
          {drawProgress > 0 && (
            <g style={{ transition: "none" }}>
              {/* Outer Bloom glow */}
              <circle
                cx={dotPos.x}
                cy={dotPos.y}
                r={dotSize * 3.2}
                fill={primaryColor}
                opacity={0.12 * endDotPulse}
                style={{ filter: "blur(12px)", transition: "none" }}
              />
              {/* Inner Radiant glow */}
              <circle
                cx={dotPos.x}
                cy={dotPos.y}
                r={dotSize * 1.8}
                fill={primaryColor}
                opacity={0.5 * endDotPulse}
                style={{ filter: "blur(4px)", transition: "none" }}
              />
              {/* White center diode core */}
              <circle
                cx={dotPos.x}
                cy={dotPos.y}
                r={dotSize * 0.75}
                fill="#ffffff"
                style={{ transition: "none" }}
              />
            </g>
          )}
        </svg>

        {/* Absolute DOM HTML overlays for Labels & Years */}

        {/* Dollar values above chart coordinates */}
        {points.map((p, i) => {
          const revealVal = getPointReveal(i);
          const opacityVal = revealVal;
          const slideUp = (1 - revealVal) * 10;

          return (
            <div
              key={`val-${p.year}`}
              style={{
                position: "absolute",
                left: p.x,
                top: p.y - 32,
                transform: `translateX(-50%) translateY(${slideUp}px)`,
                opacity: opacityVal,
                fontFamily: valuesFam,
                fontSize: "1.1vw",
                fontWeight: 600,
                color: primaryColor,
                textAlign: "center",
                textShadow: "0 2px 8px rgba(0,0,0,0.8)",
                pointerEvents: "none",
                transition: "none",
              }}
            >
              {`$${p.value.toFixed(2)}`}
            </div>
          );
        })}

        {/* Years along X-axis */}
        {points.map((p, i) => {
          const revealVal = getPointReveal(i);
          const finalColor = interpolateColors(
            revealVal,
            [0, 1],
            ["rgba(255, 255, 255, 0.35)", "#ffffff"]
          );

          return (
            <div
              key={`year-${p.year}`}
              style={{
                position: "absolute",
                left: p.x,
                top: chartBottom + 22,
                transform: "translateX(-50%)",
                fontFamily: axisFam,
                fontSize: "0.95vw",
                fontWeight: 500,
                color: finalColor,
                textAlign: "center",
                pointerEvents: "none",
                transition: "none",
              }}
            >
              {p.year}
            </div>
          );
        })}

        {/* "96% Decline" elegant side container */}
        {declineProgress > 0 && (
          <div
            style={{
              position: "absolute",
              left: points[5].x + 35,
              top: points[5].y - cardHeight * 0.1,
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              opacity: declineProgress,
              transform: `translateX(${(1 - declineProgress) * 15}px)`,
              pointerEvents: "none",
              zIndex: 3,
              transition: "none",
            }}
          >
            {/* Elegant vertical brand accent bar */}
            <div
              style={{
                width: 2.5,
                height: declineProgress * (cardHeight * 0.18),
                backgroundColor: primaryColor,
                marginRight: 16,
                boxShadow: `0 0 10px ${primaryColor}`,
                transition: "none",
              }}
            />
            {/* Core textual info column */}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
                transition: "none",
              }}
            >
              <span
                style={{
                  fontFamily: declinePercentFam,
                  fontSize: "3.5vw",
                  fontWeight: "bold",
                  color: primaryColor,
                  lineHeight: 0.9,
                  textShadow: `0 0 20px ${primaryColor}30`,
                  transition: "none",
                }}
              >
                {declinePercentage}
              </span>
              <span
                style={{
                  fontFamily: declineLabelFam,
                  fontSize: "1.1vw",
                  fontWeight: 500,
                  color: "rgba(255, 255, 255, 0.8)",
                  letterSpacing: "1px",
                  marginTop: 2,
                  textTransform: "uppercase",
                  transition: "none",
                }}
              >
                {declineLabel}
              </span>
            </div>
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default DollarDecline;